struct BroadcastObject {
    x: Vec<f32>,
    y: Vec<f32>,
}

impl BroadcastObject {
    // Method to access elements in the broadcast grid
    fn get(&self, i: usize, j: usize) -> (f32, f32) {
        (self.x[i], self.y[j])
    }
}

fn broadcast(x: Vec<f32>, y: Vec<f32>) -> BroadcastObject {
    // Ensure that the input arrays are non-empty
    assert!(!x.is_empty(), "First array must be non-empty");
    assert!(!y.is_empty(), "Second array must be non-empty");

    BroadcastObject { x, y }
}

fn main() {
    let x = vec![1.0, 2.0, 3.0];
    let y = vec![4.0, 5.0];

    let broadcast_grid = broadcast(x, y);

    // Example of accessing elements
    for i in 0..broadcast_grid.x.len() {
        for j in 0..broadcast_grid.y.len() {
            let (a, b) = broadcast_grid.get(i, j);
            println!("({}, {})", a, b);
        }
    }
}